package com.smartsociety.platform.notification; import com.smartsociety.platform.complaint.Complaint; import com.smartsociety.platform.common.Enums.ComplaintStatus; import org.slf4j.*; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service;
@Service public class NotificationService {private static final Logger log=LoggerFactory.getLogger(NotificationService.class); private final EmailService email; public NotificationService(EmailService e){email=e;} @Async public void statusChanged(Complaint c,ComplaintStatus from,ComplaintStatus to){try{email.send(c.getResident().getEmail(),"Complaint status updated", "Your complaint '"+c.getTitle()+"' changed from "+from+" to "+to+".");}catch(Exception e){log.error("Notification delivery failed for complaint {}",c.getId(),e);}} @Async public void importantNotice(String emailAddress,String title,String body){try{email.send(emailAddress,"Important society notice: "+title,body);}catch(Exception e){log.error("Important notice delivery failed",e);}} }
